<?php require_once __DIR__.'/app/core/bootstrap.php'; if(current_user()){redirect('index.php');} $title='Login'; $error=''; if(is_post()){verify_csrf();$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$st=db()->prepare('SELECT * FROM users WHERE email=? LIMIT 1');$st->bind_param('s',$email);$st->execute();$u=$st->get_result()->fetch_assoc(); if($u && password_verify($pass,$u['password_hash']) && $u['status']==='active'){login_user($u); safe_log('login','user',(int)$u['id']); if($u['role']==='admin') redirect('admin/index.php'); if($u['role']==='operator') redirect('operator/index.php'); redirect('customer/index.php');} else $error='Invalid login details or account not active.';} require __DIR__.'/app/views/header.php'; ?>
